apiData.solution:
select cou.cno 课程号,cname 课程名,count(sno) 选课人数,ifnull(max(grade),0) 最高成绩,ifnull(min(grade),0) 最低成绩,ifnull(avg(grade),0) 平均成绩 
from cou LEFT JOIN sc on(cou.cno=sc.cno)
group by cou.cno,cname;

